using namespace rinkfit;
static void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
static EventParameterBlock block(const std::string&name,std::vector<double>values){EventParameterBlock b;b.name=name;b.values=std::move(values);b.lower.assign(b.values.size(),-10.);b.upper.assign(b.values.size(),10.);b.scales.assign(b.values.size(),1.);return b;}
static EventParameterBlock from_json(const eventio::Json&j){auto b=block(j.at("name"),j.at("values").get<std::vector<double>>());b.lower=j.at("lower").get<std::vector<double>>();b.upper=j.at("upper").get<std::vector<double>>();b.scales=j.at("scales").get<std::vector<double>>();return b;}
static void actual_fixture(const char*file){const auto fixture=eventio::read_json(file);double max_fd=0.;eventio::Json rig_results=eventio::Json::array(),rejected_controls=eventio::Json::array();int valid_controls=0,affine_controls=0;bool exercised_affine_trial=false;
 for(const auto&entry:fixture.at("rigs")){const auto&camera=entry.at("camera");JointRig rig;rig.math.f_ref=camera.at("f_ref");rig.math.radius_max=camera.at("radius_max");if(camera.contains("brown_wide_extension")){rig.math.wide_coefficients=camera.at("brown_wide_extension").at("coefficients").get<std::array<double,4>>();rig.math.wide_log_f_boundary=camera.at("brown_wide_extension").at("activation_log_f_native");}auto optics=from_json(entry.at("block"));const auto range=entry.at("range").get<std::array<double,2>>();JointCaptureOpticalDomainCost gate(rig,range,&optics);const double*p[]={optics.values.data()};double residual=0.;require(gate.Evaluate(p,&residual,nullptr),"actual r9 optics rejected by unchanged certificate");double max_g=-INFINITY;
  for(int endpoint=0;endpoint<2;++endpoint){JointZoomCertificate c;c.f_ref=rig.math.f_ref;c.radius=rig.math.radius_max;c.endpoint=endpoint;c.wide_coefficients=rig.math.wide_coefficients;c.wide_boundary=rig.math.wide_log_f_boundary;using J=ceres::Jet<double,12>;J lens[12],zoom[2],g;for(int j=0;j<12;++j){lens[j].a=optics.values[j];lens[j].v.setZero();lens[j].v[j]=1.;}for(int j=0;j<2;++j)zoom[j]=J(range[j]);const J*jp[]={lens,zoom};require(c(jp,&g),"actual Brown AD failed");max_g=std::max(max_g,g.a);const double*fp[]={optics.values.data(),range.data()};
   for(int j=0;j<12;++j){const double saved=optics.values[j],h=1e-9*std::max(1.,std::abs(saved));double plus=0.,minus=0.;optics.values[j]=saved+h;require(c(fp,&plus),"actual Brown positive FD failed");optics.values[j]=saved-h;require(c(fp,&minus),"actual Brown negative FD failed");optics.values[j]=saved;{double error=std::abs((plus-minus)/(2*h)-g.v[j])/std::max(1.,std::abs(g.v[j]));if(error>2e-5)std::cerr<<"Brown FD rig="<<entry.at("id")<<" endpoint="<<endpoint<<" column="<<j<<" AD="<<g.v[j]<<" FD="<<(plus-minus)/(2*h)<<" rel="<<error<<"\n";max_fd=std::max(max_fd,error);}}}
  rig_results.push_back({{"rig",entry.at("id")},{"max_Brown_g",max_g},{"physical_gate_passed",true}});
 }
 require(max_fd<2e-5,"actual Euclidean Brown derivative regression");
 for(const auto&entry:fixture.at("controls")){auto b=from_json(entry.at("block"));const auto indices=entry.at("indices").get<std::vector<int>>();const auto range=entry.at("range").get<std::array<double,2>>();const bool affine=!entry.at("manifold").is_null();ceres::Problem problem;problem.AddParameterBlock(b.values.data(),int(b.values.size()));if(affine)problem.SetManifold(b.values.data(),new JointLinearControlManifold(entry.at("manifold")));bool outside=false;for(int index:indices)outside=outside||b.values[index]<std::max(b.lower[index],range[0])||b.values[index]>std::min(b.upper[index],range[1]);bool rejected=false;try{install_joint_capture_zoom_bounds_v1(problem,b,indices,range,affine);}catch(const std::runtime_error&){rejected=true;}require(rejected==outside,"actual S01 zoom admission differs from certified box");if(rejected){rejected_controls.push_back({{"shot",entry.at("shot")},{"block_index",entry.at("block_index")},{"name",b.name}});continue;}valid_controls+=int(indices.size());if(!affine)continue;affine_controls+=int(indices.size());double cost=0.;require(problem.Evaluate(ceres::Problem::EvaluateOptions{},&cost,nullptr,nullptr,nullptr),"actual affine initial state rejected");
  const auto*m=problem.GetManifold(b.values.data());const int n=m->AmbientSize(),k=m->TangentSize();std::vector<double>jac(n*k),seed=b.values,trial(n),delta(k,0.),back(k);require(m->PlusJacobian(seed.data(),jac.data()),"actual affine Jacobian unavailable");for(int index:indices){if(exercised_affine_trial)break;for(int j=0;j<k;++j){const double derivative=jac[index*k+j];if(std::abs(derivative)<1e-8)continue;delta[j]=(range[1]-seed[index]+.1)/derivative;require(m->Plus(seed.data(),delta.data(),trial.data())&&m->Minus(trial.data(),seed.data(),back.data()),"actual affine Plus/Minus failed");for(int c=0;c<k;++c)require(std::abs(back[c]-delta[c])<1e-7*std::max(1.,std::abs(delta[c])),"actual affine inverse changed");std::copy(trial.begin(),trial.end(),b.values.begin());require(!problem.Evaluate(ceres::Problem::EvaluateOptions{},&cost,nullptr,nullptr,nullptr),"actual affine trial left logf hull without rejection");std::copy(seed.begin(),seed.end(),b.values.begin());exercised_affine_trial=true;break;}}
 }
 require(rejected_controls.size()==8&&affine_controls==28&&exercised_affine_trial,"r9 complete-control fixture coverage differs");std::cout<<eventio::Json({{"schema","rinkfit.actual_capture_domain_regression.v1"},{"model",fixture.at("model")},{"rigs",rig_results},{"max_relative_Brown_AD_FD_error",max_fd},{"valid_control_coordinates",valid_controls},{"affine_control_coordinates",affine_controls},{"rejected_outside_control_blocks",rejected_controls},{"actual_affine_trial_checked",exercised_affine_trial},{"production_solve_started",false}}).dump(2)<<"\n";
}
static void actual_restore(const char*file){const auto fixture=eventio::read_json(file),original=eventio::read_json(fixture.at("model").get<std::string>());JointEventModel model;model.source_json=original;for(const auto&b:original.at("blocks"))model.blocks.push_back(from_json(b));for(const auto&item:original.at("shots").items()){JointShot shot;shot.id=item.key();shot.rig_id=item.value().at("rig_id");shot.control_blocks=item.value().at("control_blocks").get<std::vector<int>>();shot.control_sources=shot.control_blocks;shot.control_offsets.assign(shot.control_blocks.size(),0);if(item.value().contains("control_coordinates"))for(std::size_t k=0;k<shot.control_blocks.size();++k){shot.control_sources[k]=item.value().at("control_coordinates")[k].at("block");shot.control_offsets[k]=item.value().at("control_coordinates")[k].at("offset");}model.shots.push_back(std::move(shot));}std::map<std::string,std::array<double,2>>ranges;for(const auto&entry:fixture.at("rigs"))ranges[entry.at("id")]=entry.at("range").get<std::array<double,2>>();std::set<std::pair<int,int>>free;for(const auto&entry:fixture.at("explicitly_free"))free.insert({entry[0].get<int>(),entry[1].get<int>()});
 auto original_values=[&](){std::vector<std::vector<double>>out;for(const auto&b:model.blocks)out.push_back(b.values);return out;};const auto before=original_values();auto report=restore_joint_capture_zoom_values_v1(model,ranges,free);require(report.at("changed_scalar_count")==8,"actual feasibility restoration did not repair exactly eight direct zoom coordinates");auto expected=before;for(const auto&change:report.at("changes"))expected[change.at("block").get<std::size_t>()][change.at("component").get<std::size_t>()]=change.at("after").get<double>();require(original_values()==expected,"actual feasibility restoration changed an unlisted scalar");require(restore_joint_capture_zoom_values_v1(model,ranges,free).at("changed_scalar_count")==0,"actual feasibility restoration is not idempotent");

 const eventio::Json recovery_policy={{"schema","rinkfit.capture_zoom_feasibility_recovery.v1"},{"from_state_token","7c2fece966a82b13"},{"from_model",{{"sha256","actual-bound-model-sha"}}},{"certified_domain",{{"sha256","actual-bound-domain-sha"}}}};const eventio::Json recovery_record={{"schema","rinkfit.applied_capture_zoom_feasibility_recovery.v1"},{"policy",recovery_policy},{"original_imported_state_token","7c2fece966a82b13"},{"original_model_sha256","actual-bound-model-sha"},{"certified_domain_sha256","actual-bound-domain-sha"},{"changes",report.at("changes")},{"changed_scalar_count",8}};require(joint_capture_zoom_recovery_metadata_v1(model).is_null(),"original model falsely claims a completed zoom transition");model.runtime_model_metadata["capture_zoom_feasibility_recovery_v1"]=recovery_record;validate_joint_capture_zoom_recovery_metadata_v1(model,joint_capture_zoom_recovery_metadata_v1(model),recovery_policy,original,ranges);require(restore_joint_capture_zoom_values_v1(model,ranges,{}).at("changed_scalar_count")==0,"already-applied zoom transition projects coordinates a second time");auto tampered_record=recovery_record;tampered_record["original_imported_state_token"]="wrong";bool bad_record_rejected=false;try{validate_joint_capture_zoom_recovery_metadata_v1(model,tampered_record,recovery_policy,original,ranges);}catch(const std::runtime_error&){bad_record_rejected=true;}require(bad_record_rejected,"changed original zoom migration token accepted");tampered_record=recovery_record;tampered_record["changes"][0]["before"]=0.;bad_record_rejected=false;try{validate_joint_capture_zoom_recovery_metadata_v1(model,tampered_record,recovery_policy,original,ranges);}catch(const std::runtime_error&){bad_record_rejected=true;}require(bad_record_rejected,"forged original zoom projection scalar accepted");
 for(std::size_t i=0;i<before.size();++i)model.blocks[i].values=before[i];const auto&shot=model.shots.front();bool set_shared=false;for(const auto&s:model.shots)for(std::size_t k=0;k<s.control_sources.size()&&!set_shared;++k){const int bi=s.control_sources[k];if(model.blocks[bi].values.size()>3){model.blocks[bi].values[s.control_offsets[k]+2]=ranges.at(s.rig_id)[0]-1.;set_shared=true;}}require(set_shared,"actual shared coordinate fixture missing");const auto bad_before=original_values();bool rejected=false;try{restore_joint_capture_zoom_values_v1(model,ranges,free);}catch(const std::runtime_error&){rejected=true;}require(rejected&&original_values()==bad_before,"shared violation was clipped or changed earlier direct coordinates before failure");std::cout<<eventio::Json({{"schema","rinkfit.actual_zoom_feasibility_regression.v1"},{"actual_direct_changes",report.at("changes")},{"all_other_model_values_preserved",true},{"repeat_changed_coordinates",0},{"shared_violation_rejected_before_mutation",true},{"production_solve_started",false}}).dump(2)<<"\n";
}
int main(int argc,char**argv){try{
 JointRig rig;rig.math.radius_max=1.;rig.math.f_ref=1.;auto optics=block("rig/test/optics12",std::vector<double>(12,0.));
 bool rejected=false;try{JointOpticalFeasibleCoordinates invalid(rig,{-.5,.5},optics);}catch(const std::runtime_error&){rejected=true;}require(rejected,"old clipped manifold must fail before installation");
 // The unchanged physical Brown predicate remains a real gate with ordinary
 // Euclidean derivatives on both sides of the historical zero-gap boundary.
 JointCaptureOpticalDomainCost domain(rig,{-.5,.5},&optics);double residual=1.;const double* lens[]={optics.values.data()};
 require(domain.Evaluate(lens,&residual,nullptr)&&residual==0.,"valid Euclidean optics rejected");
 optics.values[5]=(1e-8+1e-10-1.)/3.;JointZoomCertificate certificate;certificate.f_ref=1.;certificate.radius=1.;double range[]={-.5,.5};const double* args[]={optics.values.data(),range};double base=0.;require(certificate(args,&base),"Brown predicate arithmetic failed");
 const double value=optics.values[5],h=1e-9;double gp=0.,gm=0.;optics.values[5]=value+h;require(certificate(args,&gp),"positive certificate derivative failed");require(domain.Evaluate(lens,&residual,nullptr),"feasible side of Brown boundary rejected");optics.values[5]=value-h;require(certificate(args,&gm),"negative certificate derivative failed");require(!domain.Evaluate(lens,&residual,nullptr),"infeasible side of Brown boundary admitted");require(std::abs((gp-gm)/(2*h)+3.)<1e-6,"Euclidean Brown boundary derivative mismatch");optics.values[5]=value;require(std::abs((gp-base)/h+3.)<1e-6&&std::abs((base-gm)/h+3.)<1e-6,"one-sided Brown derivatives disagree");
 // Direct S01 controls receive the same scalar hard zoom bounds as S02-S06.
 auto direct=block("shot/s01/control/0",{0.,0.,.4});ceres::Problem pd;pd.AddParameterBlock(direct.values.data(),3);auto direct_report=install_joint_capture_zoom_bounds_v1(pd,direct,{2},{0.,1.},false);require(pd.GetParameterLowerBound(direct.values.data(),2)==0.&&pd.GetParameterUpperBound(direct.values.data(),2)==1.,"direct S01 logf bound missing");require(direct_report.size()==1,"direct S01 control absent from receipt");
 direct.values[2]=-.1;rejected=false;try{install_joint_capture_zoom_bounds_v1(pd,direct,{2},{0.,1.},false);}catch(const std::runtime_error&){rejected=true;}require(rejected,"out-of-domain S01 seed silently accepted");
 // Actual affine Plus: two log-f controls share one direction.  Check its
 // pullback domain without ambient clipping, which would break the subspace.
 auto grouped=block("shot/s01/control_group/0",{0.,0.,.4,0.,0.,.6});const double a=1./std::sqrt(2.);eventio::Json basis={{"ambient_size",6},{"tangent_size",1},{"basis",{{0.},{0.},{a},{0.},{0.},{-a}}}};ceres::Problem pa;pa.AddParameterBlock(grouped.values.data(),6);pa.SetManifold(grouped.values.data(),new JointLinearControlManifold(basis));auto grouped_report=install_joint_capture_zoom_bounds_v1(pa,grouped,{2,5,2},{0.,1.},true);require(grouped_report.size()==2,"shared-control coordinates not deduplicated exactly");require(pa.GetParameterLowerBound(grouped.values.data(),2)==-std::numeric_limits<double>::max(),"affine ambient bound was clipped");
 const auto* manifold=pa.GetManifold(grouped.values.data());double seed[6],trial[6],delta[]={.1},back[1];std::copy(grouped.values.begin(),grouped.values.end(),seed);require(manifold->Plus(seed,delta,trial)&&manifold->Minus(trial,seed,back)&&std::abs(back[0]-delta[0])<1e-14,"original affine Plus/Minus damaged");std::copy(trial,trial+6,grouped.values.begin());double cost=0.;require(pa.Evaluate(ceres::Problem::EvaluateOptions{},&cost,nullptr,nullptr,nullptr),"feasible affine zoom trial rejected");delta[0]=.9;require(manifold->Plus(seed,delta,trial),"affine trial failed");require(std::abs(trial[2]+trial[5]-1.)<1e-14,"affine trial left original subspace");std::copy(trial,trial+6,grouped.values.begin());require(!pa.Evaluate(ceres::Problem::EvaluateOptions{},&cost,nullptr,nullptr,nullptr),"affine zoom pullback admitted a certified-domain violation");
 if(argc>1){actual_fixture(argv[1]);actual_restore(argv[1]);}
 std::cout<<"capture domain regression: old optical chart blocked; Brown boundary derivatives and real gate preserved; direct/shared S01 zoom bounds checked\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
